import type { Text } from '@codemirror/state';
import type { Tree } from '@lezer/common';
import type { _NumberFormatParser } from '../../../core/hooks/useParseNumber.js';
/** All the node types included in the lezer syntax tree. */
export type FilterFieldLezerNodeType = 'Filter' | 'FilterGroup' | 'FilterStatement' | 'FilterKey' | 'Identifier' | 'Duration' | 'String' | 'Number' | 'Boolean' | 'ComparisonOperator' | 'InvalidComparisonOperator' | 'ExistsOperator' | 'PositionOperator' | 'LikeOperator' | 'FilterSimpleValue' | 'FilterIncludesValue' | 'Range' | 'IncompleteRange' | 'Inclusion' | 'List' | 'IncompleteList' | 'LogicalOperator' | 'OpeningBracket' | 'ClosingBracket' | '⚠';
export type FilterFieldNodeType = 'Filter' | 'Group' | 'Statement';
export type FilterFieldNodeRange = {
    from: number;
    to: number;
};
export type FilterFieldNodeBase = {
    range: FilterFieldNodeRange;
};
export type FilterFieldGroupNode = FilterFieldNodeBase & {
    type: FilterFieldNodeType;
    children: (FilterFieldNode | undefined)[];
};
export type FilterFieldStatementNode = FilterFieldNodeBase & {
    type: 'Statement';
    key?: FilterFieldKeyNode | FilterFieldErrorNode;
    operator?: FilterFieldLeafNode;
    value?: FilterFieldLeafNode;
};
export type FilterFieldKeyNode = FilterFieldNodeBase & {
    type: 'Key';
    textValue: string;
    value: string;
};
export type FilterFieldStringNode = FilterFieldNodeBase & {
    type: 'String';
    textValue: string;
    value: string;
    isEscaped?: boolean;
    operator?: 'contains' | 'starts-with' | 'ends-with';
    like?: boolean;
};
export type FilterFieldDurationNode = FilterFieldNodeBase & {
    type: 'Duration';
    textValue: string;
    value?: number;
    unit?: 'ns' | 'ms' | 's' | 'm' | 'h' | 'd';
};
export type FilterFieldNumberNode = FilterFieldNodeBase & {
    type: 'Number';
    textValue: string;
    value: number;
};
export type FilterFieldBooleanNode = FilterFieldNodeBase & {
    type: 'Boolean';
    textValue: string;
    value: boolean;
};
export type FilterFieldListNode = FilterFieldNodeBase & {
    type: 'List';
    textValue: string;
    value: string[];
};
export type FilterFieldRangeNode = FilterFieldNodeBase & {
    type: 'Range';
    textValue: string;
    value: {
        from?: number;
        to?: number;
    };
};
export type FilterFieldLogicalOperatorNode = FilterFieldNodeBase & {
    type: 'LogicalOperator';
    textValue: 'and' | 'AND' | 'or' | 'OR';
    value: 'and' | 'AND' | 'or' | 'OR';
};
export type FilterFieldComparisonOperatorNode = FilterFieldNodeBase & {
    type: 'ComparisonOperator';
    textValue: '=' | '!=' | '<' | '<=' | '>' | '>=';
    value: '=' | '!=' | '<' | '<=' | '>' | '>=';
};
export type FilterFieldExistsOperatorNode = FilterFieldNodeBase & {
    type: 'ExistsOperator';
    textValue: string;
    value: boolean;
};
export type FilterFieldLikeOperatorNode = FilterFieldNodeBase & {
    type: 'Like';
    textValue: '?';
    value: '?';
};
export type FilterFieldInclusionOperatorNode = FilterFieldNodeBase & {
    type: 'Inclusion';
    textValue: 'in' | 'IN';
    value: 'in' | 'IN';
};
export type FilterFieldErrorNode = FilterFieldNodeBase & {
    type: 'Error';
    textValue: string;
    value: string;
};
export type FilterFieldLeafNode = FilterFieldKeyNode | FilterFieldStringNode | FilterFieldNumberNode | FilterFieldBooleanNode | FilterFieldDurationNode | FilterFieldListNode | FilterFieldRangeNode | FilterFieldLogicalOperatorNode | FilterFieldComparisonOperatorNode | FilterFieldExistsOperatorNode | FilterFieldLikeOperatorNode | FilterFieldInclusionOperatorNode | FilterFieldErrorNode;
export type FilterFieldNode = FilterFieldGroupNode | FilterFieldStatementNode | FilterFieldLeafNode;
export type FilterFieldTree = FilterFieldGroupNode['children'];
/** Iterate over the parsed document and convert the lezer tree to an object. */
export declare function convertLezerTree(tree: Tree, numberParser: _NumberFormatParser, doc?: Text): {
    tree: FilterFieldTree;
    hasError: boolean;
};
/** Get the filter statement around the given cursor position. */
export declare function getFilterStatementForSuggestions(tree: Tree, cursorPosition: number, numberParser: _NumberFormatParser, doc?: Text): FilterFieldStatementNode | undefined;
export declare function isFilterFieldLeafNode(node: unknown): node is FilterFieldLeafNode;
